def subarray_sum(nums: list[int], k: int) -> int:
    count = 0
    cur_sum = 0
    prefix_counts = {0: 1}
    for x in nums:
        cur_sum += x
        if (cur_sum - k) in prefix_counts:
            count += prefix_counts[cur_sum - k]
        prefix_counts[cur_sum] = prefix_counts.get(cur_sum, 0) + 1
    return count
